1 | /**
2 |  * models.ts — shared type contracts for sdlc-harness skill agents.
3 |  *
4 |  * These types are the single source of truth consumed by all five agents,
5 |  * the review interface (Task 25), and the telemetry module (Task 26).
6 |  * No GitLab SDK dependency — plain TypeScript interfaces only.
7 |  */
8 | 
9 | // ---------------------------------------------------------------------------
10 | // Project configuration (persisted by onboarding, Task 18)
11 | // ---------------------------------------------------------------------------
12 | 
13 | export interface TransitionRules {
14 |   [fromState: string]: string[];
15 | }
16 | 
17 | export interface ProjectConfig {
18 |   /** GitLab project URL, e.g. "http://localhost:8080/sdlc-harness/weather-dashboard" */
19 |   projectUrl: string;
20 |   /** Work item types in use, e.g. ["Story", "Bug", "Task", "Epic"] */
21 |   workItemTypes: string[];
22 |   /** Ordered workflow states, e.g. ["Open", "In Progress", "In Review", "Done"] */
23 |   workflowStates: string[];
24 |   /** Valid state transitions: { "Open": ["In Progress"], ... } */
25 |   transitionRules: TransitionRules;
26 |   /** Optional test-coverage linkage config (Task 24 — P1, disabled by default). */
27 |   coverage?: CoverageConfig;
28 | }
29 | 
30 | // ---------------------------------------------------------------------------
31 | // Lightweight issue / MR shapes (mirror the MCP server types but without the
32 | // full GitLab schema so agents work without importing the server package)
33 | // ---------------------------------------------------------------------------
34 | 
35 | export interface IssueInput {
36 |   iid: number;
37 |   title: string;
38 |   description: string | null;
39 |   labels: string[];
40 |   state: string;
41 |   assignee: unknown | null;
42 | }
43 | 
44 | export interface MRInput {
45 |   iid: number;
46 |   title: string;
47 |   description: string | null;
48 |   state: string;
49 |   mergedAt?: string | null;
50 | }
51 | 
52 | // ---------------------------------------------------------------------------
53 | // Agent finding types
54 | // ---------------------------------------------------------------------------
55 | 
56 | /** Discriminator tags for each agent. */
57 | export type AgentTag = 'AC' | 'AM' | 'DEP' | 'ST' | 'COV';
58 | 
59 | /**
60 |  * A finding produced by any single-issue agent (AC, AM, ST, COV).
61 |  */
62 | /**
63 |  * What an agent hands to the drafter. Agents detect; they do not write prose.
64 |  *
65 |  * `context` is everything the drafter may ground the text in. `unknowns` are
66 |  * gaps the issue does not fill — the drafter must ask about these rather than
67 |  * invent a plausible value, which is the failure mode that makes generated
68 |  * work items worse than no work items.
69 |  */
70 | export interface DraftBrief {
71 |   task: string;
72 |   context: Record<string, string>;
73 |   unknowns: string[];
74 | }
75 | 
76 | export interface AgentFinding {
77 |   /** Agent that produced this finding. */
78 |   agent: AgentTag;
79 |   /** The issue this finding relates to. */
80 |   issueIid: number;
81 |   /**
82 |    * Short action label for the finding type.
83 |    *  'draft_ac'         — AC agent drafted missing acceptance criteria
84 |    *  'rewrite_desc'     — AM agent proposed a description rewrite
85 |    *  'state_transition' — ST agent proposed a state change
86 |    *  'missing_coverage' — COV agent flagged an issue with no test reference
87 |    */
88 |   action: 'draft_ac' | 'rewrite_desc' | 'state_transition' | 'missing_coverage';
89 |   /** The proposed new value (AC text, rewritten description, or target state). */
90 |   suggestedValue: string;
91 |   /**
92 |    * Present when the text still has to be written. The drafter replaces
93 |    * suggestedValue with its own prose and clears this field; applyFinding
94 |    * refuses to write a finding that still carries one.
95 |    */
96 |   draft?: DraftBrief;
97 |   /** Human-readable explanation of why this finding was raised. Optional. */
98 |   reason?: string;
99 | }
100 | 
101 | /**
102 |  * A dependency finding produced by the dependency agent (Task 22).
103 |  * Separate type because it spans two issues.
104 |  */
105 | export interface DependencyFinding {
106 |   agent: 'DEP';
107 |   /** Source issue IID (the one that depends on / blocks the other). */
108 |   sourceIid: number;
109 |   /** Target issue IID. */
110 |   targetIid: number;
111 |   /** Proposed link type. */
112 |   suggestedLinkType: 'blocks' | 'relates-to';
113 |   /** Human-readable explanation. */
114 |   reason?: string;
115 |   /** Confidence score in [0,1]. */
116 |   confidence: number;
117 | }
118 | 
119 | /** Union of all finding types surfaced to the review interface. */
120 | export type AnyFinding = AgentFinding | DependencyFinding;
121 | 
122 | // ---------------------------------------------------------------------------
123 | // Review interface types (Task 25)
124 | // ---------------------------------------------------------------------------
125 | 
126 | /**
127 |  * Outcome of a review decision.
128 |  *  - 'accepted' — user accepted the suggestion and it was successfully written to GitLab.
129 |  *  - 'edited'   — user edited the suggestion and it was successfully written to GitLab.
130 |  *  - 'rejected' — user rejected the suggestion; nothing was written.
131 |  *  - 'failed'   — user accepted or edited the suggestion but the write to GitLab failed
132 |  *                 (adapter returned written:false). The suggestion did NOT reach GitLab.
133 |  *                 'failed' entries are excluded from both the numerator and denominator
134 |  *                 of acceptance-rate statistics so they do not inflate the reported rate.
135 |  */
136 | export type ReviewOutcome = 'accepted' | 'edited' | 'rejected' | 'failed';
137 | 
138 | export interface ReviewOptions {
139 |   /** Provide an edited value to apply instead of the suggestion; null means use as-is. */
140 |   editedValue: string | null;
141 | }
142 | 
143 | export interface ReviewResult {
144 |   /** Whether the GitLab writer adapter was called. */
145 |   gitlabWriteCalled: boolean;
146 |   /** The value actually written (finding's suggestion or the edited value). */
147 |   writtenValue?: string;
148 |   /** Safe diagnostic when the GitLab write did not complete. */
149 |   error?: string;
150 |   /** Telemetry entry appended for this decision. */
151 |   telemetryEntry: TelemetryEntry;
152 | }
153 | 
154 | // ---------------------------------------------------------------------------
155 | // Telemetry types (Task 26)
156 | // ---------------------------------------------------------------------------
157 | 
158 | export interface TelemetryEntry {
159 |   /** ISO-8601 timestamp of the decision. */
160 |   timestamp: string;
161 |   /** Agent that produced the finding. */
162 |   agent: AgentTag;
163 |   /** Issue IID the finding was about. */
164 |   issueIid: number;
165 |   /** The action / finding type. */
166 |   action: string;
167 |   /** What the user decided. */
168 |   outcome: ReviewOutcome;
169 |   /**
170 |    * Fields that were edited (empty array for 'accepted' / 'rejected').
171 |    * Only 'description' is used in the current agent set.
172 |    */
173 |   editedFields: string[];
174 | }
175 | 
176 | // ---------------------------------------------------------------------------
177 | // Test-coverage linkage types (Task 24 — P1)
178 | // ---------------------------------------------------------------------------
179 | 
180 | export interface CoverageConfig {
181 |   /** Glob patterns for test files to scan, e.g. ["**\/*.test.ts", "tests/**\/*.ts"] */
182 |   testFilePatterns: string[];
183 |   /** Whether the agent is enabled (disabled by default). */
184 |   enabled: boolean;
185 | }
186 | 
187 | export interface CoverageFinding extends AgentFinding {
188 |   agent: 'COV';
189 |   action: 'missing_coverage';
190 | }
