Contents of file bob-kit/skills/sdlc-harness/src/agents/ac-agent.ts:

1 | import type { IssueInput, ProjectConfig, AgentFinding, DraftBrief } from '../models';
2 | 
3 | const AC_HEADINGS = [/acceptance.criteria/i, /##\s*ac\b/i, /##\s*criteria/i];
4 | 
5 | /**
6 |  * Real acceptance criteria are structured — each clause opens its own line.
7 |  * Matching the three keywords anywhere would swallow ordinary prose such as
8 |  * "Given the deadline is tight, when we ship this, then keep scope small."
9 |  */
10 | function hasStructuredGWT(text: string): boolean {
11 |   return (
12 |     /^\s*(\*\*)?given\b/im.test(text) &&
13 |     /^\s*(\*\*)?when\b/im.test(text) &&
14 |     /^\s*(\*\*)?then\b/im.test(text)
15 |   );
16 | }
17 | 
18 | export function hasAcceptanceCriteria(description: string | null): boolean {
19 |   if (!description || !description.trim()) return false;
20 |   return AC_HEADINGS.some((re) => re.test(description)) || hasStructuredGWT(description);
21 | }
22 | 
23 | /** Label vocabulary shared with the work-item-format MCP tool. */
24 | const TYPE_BY_LABEL: Array<[RegExp, string]> = [
25 |   [/\bbug\b|\bdefect\b/i, 'Bug'],
26 |   [/\bepic\b/i, 'Epic'],
27 |   [/\bfeature\b/i, 'Feature'],
28 |   [/\btask\b|\bchore\b/i, 'Task'],
29 | ];
30 |

