arguments.command:
$gitlabToken = "glpat-REDACTED000000000000000000"
$baseUrl = "http://localhost:8080/api/v4"
$projectId = 1

# Check existing links on #3 to confirm what was created
$links = Invoke-RestMethod -Uri "$baseUrl/projects/$projectId/issues/3/links" `
  -Headers @{"PRIVATE-TOKEN" = $gitlabToken}
$links | ForEach-Object { Write-Host "link: #$($_.iid) '$($_.title)' link_type=$($_.link_type)" }

# Now try valid link_type values for this version
foreach ($lt in @("relates_to", "blocks", "is_blocked_by")) {
  $body = @{ target_project_id = $projectId; target_issue_iid = 7; link_type = $lt } | ConvertTo-Json -Compress
  try {
    $r = Invoke-RestMethod -Uri "$baseUrl/projects/$projectId/issues/1/links" -Method POST `
      -Headers @{"PRIVATE-TOKEN" = $gitlabToken; "Content-Type" = "application/json"} `
      -Body $body -ErrorAction Stop
    Write-Host "VALID: link_type='$lt' -> link_id=$($r.source_issue.iid)"
    # delete it immediately
    $linkId = $r.id
    Invoke-RestMethod -Uri "$baseUrl/projects/$projectId/issues/1/links/$linkId" -Method DELETE `
      -Headers @{"PRIVATE-TOKEN" = $gitlabToken} | Out-Null
  } catch {
