  state: 'opened',
  assignee: null,
};

/** Issue with vague language */
const ISSUE_VAGUE = {
  iid: 7,
  title: 'Fix the thing on the settings page',
  description: 'The settings page does not work properly. Fix it.',
  labels: ['Bug'],
  state: 'opened',
  assignee: null,
};

