Contents of file weather-app/app.js:

1 | /**
2 |  * app.js – Weather Dashboard (SDLC Harness Demo)
3 |  *
4 |  * This file owns all runtime behaviour:
5 |  *  - Mock weather data generation (deterministic, city-name based)
6 |  *  - Search form submission and validation
7 |  *  - Loading state management
8 |  *  - Weather card rendering
9 |  *  - Light/dark theme toggle with localStorage persistence
10 |  */
11 | 
12 | /* ------------------------------------------------------------------ */
13 | /* 1. Mock data                                                        */
14 | /*                                                                     */
15 | /* There is no external API.  Instead we derive pseudo-random but      */
16 | /* stable values from the city name using a simple hash function so    */
17 | /* that the same city always returns the same numbers, which makes     */
18 | /* demo walkthroughs repeatable.                                       */
19 | /* ------------------------------------------------------------------ */
20 | 
21 | /**
22 |  * A small set of weather conditions to choose from.
23 |  * @type {string[]}
24 |  */
25 | const WEATHER_CONDITIONS = [
26 |   'Sunny', 'Partly Cloudy', 'Overcast', 'Light Rain',
27 |   'Thunderstorm', 'Snow Flurries', 'Foggy', 'Windy', 'Clear',
28 | ];
29 | 
30 | /**
31 |  * Compute a simple, non-cryptographic hash of a string.
32 |  * Returns a non-negative integer.  Used to seed mock data from the
33 |  * city name so results are deterministic.
34 |  *
35 |  * @param {string} str
36 |  * @returns {number}
37 |  */
38 | function hashString(str) {
39 |   let hash = 0;
40 |   for (let i = 0; i < str.length; i++) {
41 |     hash = (hash * 31 + str.charCodeAt(i)) >>> 0; // keep unsigned 32-bit
42 |   }
43 |   return hash;
44 | }
45 | 
46 | /**
47 |  * Generate deterministic mock weather data for the given city.
48 |  *
49 |  * @param {string} city  City name as entered by the user.
50 |  * @returns {{city: string, tempF: number, condition: string, humidity: string, wind: string, updatedAt: string}}
51 |  */
52 | function getMockWeather(city) {
53 |   const seed = hashString(city.toLowerCase().trim());
54 | 
55 |   // Temperature: 20 °F – 100 °F range
56 |   const tempF = 20 + (seed % 81);
57 | 
58 |   // Pick a condition from the list
59 |   const condition = WEATHER_CONDITIONS[seed % WEATHER_CONDITIONS.length];
60 | 
61 |   // Humidity: 20 % – 95 %
62 |   const humidity = (20 + ((seed >> 4) % 76)) + '%';
63 | 
64 |   // Wind speed: 0 – 40 mph
65 |   const wind = ((seed >> 8) % 41) + ' mph';
66 | 
67 |   // Current timestamp
68 |   const now = new Date();
69 |   const updatedAt = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
70 | 
71 |   return {
72 |     city: toTitleCase(city.trim()),
73 |     tempF,
74 |     condition,
75 |     humidity,
76 |     wind,
77 |     updatedAt,
78 |   };
79 | }
80 | 
81 | /**
82 |  * Convert a string to title case (first letter of each word capitalised).
83 |  *
84 |  * @param {string} str
85 |  * @returns {string}
86 |  */
87 | function toTitleCase(str) {
88 |   return str.replace(/\w\S*/g, (word) => word.charAt(0).toUpperCase() + word.slice(1).toLowerCase());
89 | }
90 | 
91 | /* ------------------------------------------------------------------ */
92 | /* 2. DOM references                                                   */
93 | /* ------------------------------------------------------------------ */
94 | const searchForm        = document.getElementById('search-form');
95 | const cityInput         = document.getElementById('city-input');
96 | const searchBtn         = document.getElementById('search-btn');
97 | const validationMsg     = document.getElementById('validation-message');
98 | const loadingOverlay    = document.getElementById('loading-overlay');
99 | const cardCity          = document.getElementById('card-city');
100 | const cardTemp          = document.getElementById('card-temp');
101 | const cardCondition     = document.getElementById('card-condition');
102 | const cardHumidity      = document.getElementById('card-humidity');
103 | const cardWind          = document.getElementById('card-wind');
104 | const cardUpdated       = document.getElementById('card-updated');
105 | const themeToggleBtn    = document.getElementById('theme-toggle');
106 | 
107 | /* ------------------------------------------------------------------ */
108 | /* 3. UI state helpers                                                  */
109 | /* ------------------------------------------------------------------ */
110 | 
111 | /**
112 |  * Update the weather card with new data.
113 |  *
114 |  * @param {{city: string, tempF: number, condition: string, humidity: string, wind: string, updatedAt: string}} data
115 |  */
116 | function renderWeatherCard(data) {
117 |   cardCity.textContent      = data.city;
118 |   cardTemp.textContent      = data.tempF;
119 |   cardCondition.textContent = data.condition;
120 |   cardHumidity.textContent  = data.humidity;
121 |   cardWind.textContent      = data.wind;
122 |   cardUpdated.textContent   = 'Last updated: ' + data.updatedAt;
123 | }
124 | 
125 | /**
126 |  * Show or hide the loading overlay that sits above the weather card.
127 |  * The search button is disabled while loading to prevent duplicate requests.
128 |  *
129 |  * @param {boolean} isLoading
130 |  */
131 | function setLoading(isLoading) {
132 |   loadingOverlay.hidden = !isLoading;
133 |   searchBtn.disabled    = isLoading;
134 | }
135 | 
136 | /**
137 |  * Show a validation error on the input.
138 |  * Clears automatically on the next successful search.
139 |  *
140 |  * @param {string} message  Human-readable error text.
141 |  */
142 | function showValidationError(message) {
143 |   validationMsg.textContent = message;
144 |   cityInput.classList.add('is-invalid');
145 |   cityInput.setAttribute('aria-invalid', 'true');
146 | }
147 | 
148 | /** Remove any active validation error state. */
149 | function clearValidationError() {
150 |   validationMsg.textContent = '';
151 |   cityInput.classList.remove('is-invalid');
152 |   cityInput.removeAttribute('aria-invalid');
153 | }
154 | 
155 | /* ------------------------------------------------------------------ */
156 | /* 4. Search handler                                                   */
157 | /*                                                                     */
158 | /* Simulates an async data fetch with a short setTimeout so the       */
159 | /* loading state is visible during a demo walkthrough.                 */
160 | /* ------------------------------------------------------------------ */
161 | 
162 | /**
163 |  * Validate input, show loading, then render mock weather data.
164 |  */
165 | function handleSearch() {
166 |   const city = cityInput.value.trim();
167 | 
168 |   // Validate: city must not be empty
169 |   if (!city) {
170 |     showValidationError('Please enter a city name before searching.');
171 |     cityInput.focus();
172 |     return;
173 |   }
174 | 
175 |   clearValidationError();
176 |   setLoading(true);
177 | 
178 |   // Simulate a short network delay (300 ms) to exercise the loading state
179 |   setTimeout(function () {
180 |     const data = getMockWeather(city);
181 |     renderWeatherCard(data);
182 |     setLoading(false);
183 |     // Clear the input after a successful search for a clean UX
184 |     cityInput.value = '';
185 |   }, 300);
186 | }
187 | 
188 | /* ------------------------------------------------------------------ */
189 | /* 5. Event listeners                                                  */
190 | /* ------------------------------------------------------------------ */
191 | 
192 | // Form submission (button click or Enter key inside the input)
193 | searchForm.addEventListener('submit', function (event) {
194 |   event.preventDefault();
195 |   handleSearch();
196 | });
197 | 
198 | // Clear validation error as soon as the user starts typing again
199 | cityInput.addEventListener('input', function () {
200 |   if (cityInput.classList.contains('is-invalid')) {
201 |     clearValidationError();
202 |   }
203 | });
204 | 
205 | /* ------------------------------------------------------------------ */
206 | /* 6. Theme toggle                                                     */
207 | /*                                                                     */
208 | /* The theme is stored in localStorage under the key 'sdlc-theme'.   */
209 | /* On load we apply any saved preference before painting the page.    */
210 | /* ------------------------------------------------------------------ */
211 | 
212 | const THEME_STORAGE_KEY = 'sdlc-theme';
213 | const DARK_THEME        = 'dark';
214 | const LIGHT_THEME       = 'light';
215 | 
216 | /**
217 |  * Apply a theme to <body> and update the toggle button's accessible
218 |  * label and visible text.
219 |  *
220 |  * @param {'light'|'dark'} theme
221 |  */
222 | function applyTheme(theme) {
223 |   const isDark = theme === DARK_THEME;
224 |   document.body.setAttribute('data-theme', theme);
225 | 
226 |   // Update ARIA state and visible label so the button always describes
227 |   // what will happen next (i.e. "Switch to dark mode" when in light mode)
228 |   themeToggleBtn.setAttribute('aria-pressed', String(isDark));
229 |   themeToggleBtn.setAttribute('aria-label', isDark ? 'Switch to light mode' : 'Switch to dark mode');
230 |   themeToggleBtn.querySelector('.toggle-icon').textContent  = isDark ? '☀️' : '🌙';
231 |   themeToggleBtn.querySelector('.toggle-label').textContent = isDark ? 'Light' : 'Dark';
232 | }
233 | 
234 | /** Toggle between light and dark and persist the choice. */
235 | function toggleTheme() {
236 |   const current = document.body.getAttribute('data-theme') || LIGHT_THEME;
237 |   const next    = current === DARK_THEME ? LIGHT_THEME : DARK_THEME;
238 |   applyTheme(next);
239 |   localStorage.setItem(THEME_STORAGE_KEY, next);
240 | }
241 | 
242 | themeToggleBtn.addEventListener('click', toggleTheme);
243 | 
244 | /* ------------------------------------------------------------------ */
245 | /* 7. Initialisation                                                   */
246 | /*                                                                     */
247 | /* Runs once when the script is first parsed (deferred by placement   */
248 | /* at the bottom of <body>).  Restores saved theme and shows a        */
249 | /* default weather card so the page is never empty on first load.     */
250 | /* ------------------------------------------------------------------ */
251 | 
252 | (function init() {
253 |   // Restore saved theme preference (falls back to light)
254 |   const savedTheme = localStorage.getItem(THEME_STORAGE_KEY) || LIGHT_THEME;
255 |   applyTheme(savedTheme);
256 | 
257 |   // Show a default weather card for "New York" on first load
258 |   renderWeatherCard(getMockWeather('New York'));
259 | }());
